package dev.migmags.aifilter;

import java.text.Normalizer;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Experimental, metadata-only filter. Not wired into SmartTube's feed yet.
 * A match is a heuristic, not proof that a video was AI-generated.
 */
public final class SlopRules {
    private static final String[] TITLE_PHRASES = {
        "ai generated", "ai-generated", "made with ai", "generated by ai",
        "ai voice", "ai narration", "ai cover", "ai music",
        "faceless ai", "ai story", "ai stories",
        "midjourney", "suno ai", "udio ai", "text to video",
        "synthetic voice", "deepfake"
    };

    private final Set<String> blockedChannels = new HashSet<>();
    private final Set<String> allowedChannels = new HashSet<>();
    private boolean blockShorts;

    public void blockChannel(String channelId) {
        String key = normalize(channelId);
        if (!key.isEmpty()) blockedChannels.add(key);
    }

    public void allowChannel(String channelId) {
        String key = normalize(channelId);
        if (!key.isEmpty()) allowedChannels.add(key);
    }

    public void setBlockShorts(boolean value) {
        blockShorts = value;
    }

    public boolean shouldHide(String title, String channelId, boolean isShort) {
        String channel = normalize(channelId);
        if (!channel.isEmpty() && allowedChannels.contains(channel)) return false;
        if (!channel.isEmpty() && blockedChannels.contains(channel)) return true;
        if (blockShorts && isShort) return true;
        String normalizedTitle = normalize(title);
        return Arrays.stream(TITLE_PHRASES).anyMatch(phrase -> normalizedTitle.contains(phrase));
    }

    private static String normalize(String text) {
        if (text == null) return "";
        String lower = Normalizer.normalize(text, Normalizer.Form.NFKC)
            .toLowerCase(Locale.ROOT);
        return lower.replaceAll("\\s+", " ").trim();
    }
}
